/// The items below are pub(crate).
/// One row of the quick open or command palette.
#[derive(Clone, Debug, PartialEq, Eq)]
struct PaletteRow {
    pub label: String,
    pub detail: String,
    /// Scalar indexes into `detail` that the query matched.
    pub positions: Vec<usize>,
}

/// The items below are pub(crate).
/// Rows for the paths that match `query`, best first, at most `limit`.
fn quick_open_rows(paths: &[String], query: &str, limit: usize) -> Vec<PaletteRow>
/// `selected` moved by `delta` with wrap around. `count` 0 returns 0.
fn step_selection(selected: usize, count: usize, delta: i32) -> usize
